(function(Drupal,drupalSettings,once){'use strict';Drupal.behaviors.liveMarketSession={attach:function(context){const elements=once('live-market-session','#session-badge',context);elements.forEach(function(badgeEl){const sessionData=drupalSettings.live_market.session;function formatDate(val){const lang=document.documentElement.lang||'fr';const locale=lang==='ar'?'ar-MA':lang==='en'?'en-US':'fr-FR';let date;if(!val)date=new Date();else if(typeof val==='number')date=new Date(val<10000000000?val*1000:val);else date=new Date(val);if(isNaN(date.getTime()))date=new Date();return date.toLocaleDateString(locale,{weekday:'short',day:'2-digit',month:'short',year:'numeric'});}function formatTime(date){const lang=document.documentElement.lang||'fr';const locale=lang==='ar'?'ar-MA':lang==='en'?'en-US':'fr-FR';return date.toLocaleTimeString(locale,{hour:'2-digit',minute:'2-digit',second:'2-digit'});}let currentH=(sessionData.time&&sessionData.time.h!==undefined)?Number(sessionData.time.h):0;let currentM=(sessionData.time&&sessionData.time.m!==undefined)?Number(sessionData.time.m):0;let currentS=(sessionData.time&&sessionData.time.s!==undefined)?Number(sessionData.time.s):0;function formatTimeString(){const hh=String(currentH).padStart(2,'0');const mm=String(currentM).padStart(2,'0');const ss=String(currentS).padStart(2,'0');return hh+':'+mm+':'+ss;}function updateClock(){const lang=document.documentElement.lang||'fr';const status=sessionData.status||'closed';const sessionTimestamp=sessionData.timestamp;let label='Séance';if(sessionData.labels&&sessionData.labels[status])label=sessionData.labels[status][lang]||sessionData.labels[status]['fr'];let displayValue=label+' • '+formatDate(sessionTimestamp);if(status==='open')displayValue+=' • '+formatTimeString();badgeEl.textContent=displayValue;if(status==='closed'){badgeEl.style.background='rgba(239, 68, 68, 0.2)';badgeEl.style.color='#EF4444';badgeEl.style.borderColor='#EF4444';}else{badgeEl.style.background='rgba(16,185,129,0.2)';badgeEl.style.color='#10B981';badgeEl.style.borderColor='#10B981';}}updateClock();document.addEventListener('langchange',function(){updateClock();});});}};})(Drupal,drupalSettings,once);;
(function(Drupal,drupalSettings,once){'use strict';Drupal.behaviors.liveMarketTicker={attach:function(context){const elements=once('live-market-ticker','#market-ticker',context);elements.forEach(function(tickerEl){const track=tickerEl.querySelector('#ticker-track');if(!track)return;const tickerData=drupalSettings.live_market.ticker.items;if(!tickerData||!tickerData.length)return;function buildTicker(){const tripled=[...tickerData,...tickerData,...tickerData];const lang=document.documentElement.lang||'fr';track.innerHTML=tripled.map((s)=>{const up=s.change_pct>0;const down=s.change_pct<0;const label=s.label[lang]||s.label['fr']||s.symbol;const arrow=up?`<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#10B981" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/></svg>`:(down?`<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#EF4444" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 18 13.5 8.5 8.5 13.5 1 6"/><polyline points="17 18 23 18 23 12"/></svg>`:'');const color=up?'#10B981':(down?'#EF4444':'#94A3B8');return `
              <div class="ticker-item">
                <span class="ticker-sym">${label}</span>
                <span class="ticker-price">${s.price.toLocaleString('fr-FR',{minimumFractionDigits:2})}</span>
                <div class="ticker-chg" style="color:${color}">
                  ${arrow}
                  <span>${up?'+':''}${s.change_pct.toFixed(2)}%</span>
                </div>
              </div>
            `;}).join('');}buildTicker();document.addEventListener('langchange',buildTicker);});}};})(Drupal,drupalSettings,once);;
